func() {
	f.checkRaces()
	if f.Failed() {
		numFailed.Add(1)
	}
	err := recover()
	if err == nil {
		f.mu.RLock()
		fuzzNotCalled := !f.fuzzCalled && !f.skipped && !f.failed
		if !f.finished && !f.skipped && !f.failed {
			err = errNilPanicOrGoexit
		}
		f.mu.RUnlock()
		if fuzzNotCalled && err == nil {
			f.Error("returned without calling F.Fuzz, F.Fail, or F.Skip")
		}
	}
	didPanic := false
	defer func() {
		if !didPanic {
			f.signal <- true
		}
	}()
	doPanic := func(err any) {
		f.Fail()
		if r := f.runCleanup(recoverAndReturnPanic); r != nil {
			f.Logf("cleanup panicked with %v", r)
		}
		for root := &f.common; root.parent != nil; root = root.parent {
			root.mu.Lock()
			root.duration += highPrecisionTimeSince(root.start)
			d := root.duration
			root.mu.Unlock()
			root.flushToParent(root.name, "--- FAIL: %s (%s)\n", root.name, fmtDuration(d))
		}
		didPanic = true
		panic(err)
	}
	if err != nil {
		doPanic(err)
	}
	f.duration += highPrecisionTimeSince(f.start)
	if len(f.sub) > 0 {
		f.tstate.release()
		close(f.barrier)
		for _, sub := range f.sub {
			<-sub.signal
		}
		cleanupStart := highPrecisionTimeNow()
		err := f.runCleanup(recoverAndReturnPanic)
		f.duration += highPrecisionTimeSince(cleanupStart)
		if err != nil {
			doPanic(err)
		}
	}
	f.report()
	f.done = true
	f.setRan()
}
